package main

import (
	"bufio"
	"fmt"
	"os"
)

const MD int64 = 998244353

var ff, gg []int64

func power(a int64, k int64) int64 {
	if k == 0 {
		return 1
	}
	p := power(a, k>>1)
	p = p * p % MD
	if (k & 1) == 1 {
		p = p * a % MD
	}
	return p
}

func ch(n, k int) int64 {
	return ff[n] * gg[k] % MD * gg[n-k] % MD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k_ int64
	fmt.Fscan(in, &n, &k_)
	if k_ >= int64(n) {
		fmt.Println(0)
		return
	}
	c := n - int(k_)
	ff = make([]int64, n+n)
	gg = make([]int64, n+n)
	f := int64(1)
	for i := 0; i < n+n; i++ {
		ff[i] = f
		gg[i] = power(f, MD-2)
		f = f * int64(i+1) % MD
	}
	var ans int64 = 0
	for a := 1; a <= c; a++ {
		x := power(int64(a), int64(n)) * ch(c, a) % MD
		if (c-a)%2 == 0 {
			ans += x
		} else {
			ans -= x
		}
	}
	ans %= MD
	if ans < 0 {
		ans += MD
	}
	ans = ans * ch(n, c) % MD
	if k_ > 0 {
		ans = ans * 2 % MD
	}
	fmt.Println(ans)
}

